llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Tetrabenazine has very low oral systemic availability (mean 4.9%) in patients, supporting low F for a lipophilic drug with extensive first-pass/absorption limitations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Felodipine absolute oral bioavailability in humans is 15%, below the 20% threshold, supporting low F for a lipophilic, high-clearance drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Tegaserod absolute bioavailability is approximately 10% in healthy volunteers, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Testosterone undecanoate, a long-chain fatty acid ester prodrug, has absolute oral bioavailability of 6.83% in young women, supporting low F for the similarly lipophilic ester-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Dimethandrolone undecanoate shows poor and inconsistent oral bioavailability in men, supporting low F for long-chain undecanoate esters.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Nimodipine mean oral bioavailability is 15.9% with most individual values below 20%, supporting low F for a lipophilic dihydropyridine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Nitrendipine absolute bioavailability from a 20 mg tablet is 10.7 ± 4.7%, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Batimastat has poor oral bioavailability in humans, supporting low F for a poorly absorbed lipophilic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Delmopinol bioavailability after oral administration is very low in humans, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "One nitrendipine report gives 40% oral bioavailability in normal subjects, which would be above threshold, but it is an outlier against multiple absolute bioavailability studies and has low structural transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a locally acting lipase inhibitor with negligible systemic absorption; all transferable experimental evidence from lipophilic, poorly absorbed drugs and long-chain fatty acid esters points to oral bioavailability far below 20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for orlistat is included in the provided records.",
    "Most analog records are from structurally different drug classes; transferability is based on shared lipophilicity, ester/long-chain character, and poor systemic absorption rather than identical mechanism.",
    "Some nitrendipine records report F above 20%, but they are outliers and not mechanistically transferable to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

